import { internalURL, navigationClick } from "@kasperrt/smolter/utils";
import type { Router } from "@kasperrt/smolter/preact";

export function handleLink(event: MouseEvent, anchor: HTMLAnchorElement, router: Router) {
  if (!navigationClick(event, anchor)) return;

  const target = internalURL(router.getSnapshot().url, anchor.href);
  if (!target) return;

  event.preventDefault();
  void router.navigate(target.href);
}
